mapper.select:
select latr.id, latr.activity_id, latr.task_item_id, latr.create_user_id, latr.update_user_id, latr.create_time, latr.update_time from la_activity_task_relation latr
and latr.is_delete = 0
and latr.activity_id = #{param.activityId}
and latr.task_item_id = #{param.taskItemId}
and latr.create_user_id = #{param.createUserId}
and latr.update_user_id = #{param.updateUserId}
order by latr.id desc
